#include "../include/provisioning_portal.h"
#include <WiFi.h>
ProvisioningPortal::ProvisioningPortal(ConfigManager&m,DeviceConfiguration&c):_manager(m),_config(c),_server(80){}
static String htmlEscape(String value){value.replace("&","&amp;");value.replace("<","&lt;");value.replace(">","&gt;");value.replace("\"","&quot;");value.replace("'","&#39;");return value;}
String ProvisioningPortal::page()const{String options;int count=WiFi.scanNetworks();for(int i=0;i<count;++i)options+="<option>"+htmlEscape(WiFi.SSID(i))+"</option>";String h="<!doctype html><meta name=viewport content='width=device-width'><title>RFID Setup</title><style>body{font:16px system-ui;max-width:520px;margin:30px auto;padding:20px;color:#172033}input,button{box-sizing:border-box;width:100%;padding:12px;margin:6px 0 16px;border:1px solid #ccd3dd;border-radius:8px}button{background:#741b2b;color:white;border:0}</style>";h+="<h2>RFID Scanner Setup</h2><p>Device: "+htmlEscape(_config.deviceId)+"</p><form method=post action=/save><label>Wi-Fi SSID</label><input name=ssid list=n value='"+htmlEscape(_config.wifiSsid)+"'><datalist id=n>"+options+"</datalist><label>Wi-Fi password</label><input type=password name=password placeholder='Leave blank to keep current password'><label>Laravel server URL</label><input name=url value='"+htmlEscape(_config.serverUrl)+"' required><label>Device ID</label><input name=device_id value='"+htmlEscape(_config.deviceId)+"' required><label>Device token</label><input type=password name=token placeholder='Leave blank to keep current token'><button>Save and connect</button></form>";return h;}
void ProvisioningPortal::begin(){if(_active)return;WiFi.mode(WIFI_AP_STA);String suffix=_config.deviceId.length()>=3?_config.deviceId.substring(_config.deviceId.length()-3):"NEW";WiFi.softAP(("RFID-SETUP-"+suffix).c_str());_server.on("/",HTTP_GET,[this](){_server.send(200,"text/html",page());});_server.on("/save",HTTP_POST,[this](){DeviceConfiguration next=_config;next.wifiSsid=_server.arg("ssid");if(_server.arg("password").length())next.wifiPassword=_server.arg("password");next.serverUrl=_server.arg("url");next.deviceId=_server.arg("device_id");if(_server.arg("token").length())next.deviceToken=_server.arg("token");if(!_manager.validateConfiguration(next,true)){_server.send(422,"text/plain","Invalid configuration");return;}_manager.savePendingConfiguration(next);_server.send(200,"text/html","<h2>Saved</h2><p>The scanner will test the network and roll back on failure.</p>");delay(500);ESP.restart();});_server.begin();_active=true;}
void ProvisioningPortal::loop(){if(_active)_server.handleClient();}
